<?php
require_once __DIR__ . '/db.php';
$user=require_login();$admin=is_admin($user);$pdo=db();$error='';$sectors=['engenharia','administrativo','obras'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!valid_csrf($_POST['csrf_token']??null))$error='Sessão expirada. Recarregue e tente novamente.';
 else{$action=$_POST['action']??'';
  if(in_array($action,['create_meta','update_meta','create_event'],true)){if(!$admin){http_response_code(403);exit('Somente administradoras podem alterar metas ou adicionar itens ao calendário.');}
   if($action==='create_meta'){$title=trim($_POST['titulo']??'');$sector=$user['setor'];$start=$_POST['semana_inicio']??'';$end=$_POST['semana_fim']??'';if($title===''||!in_array($sector,$sectors,true)||!$start||!$end||$end<$start)$error='Preencha título e período válido.';else{$stmt=$pdo->prepare('INSERT INTO metas(titulo,descricao,setor,semana_inicio,semana_fim,criada_por) VALUES(?,?,?,?,?,?)');$stmt->execute([$title,trim($_POST['descricao']??'')?:null,$sector,$start,$end,$user['id']]);header('Location: '.app_path('calendario.html?salvo=meta'));exit;}}
   elseif($action==='update_meta'){$id=(int)($_POST['meta_id']??0);$progress=filter_var($_POST['progresso']??null,FILTER_VALIDATE_FLOAT);if($id<1||$progress===false||$progress<0||$progress>100)$error='O progresso deve ser entre 0 e 100.';else{$check=$pdo->prepare('SELECT id FROM metas WHERE id=? AND setor=?');$check->execute([$id,$user['setor']]);if(!$check->fetch())$error='Meta não encontrada no seu setor.';else{$stmt=$pdo->prepare('UPDATE metas SET progresso_percentual=?,status=? WHERE id=? AND setor=?');$stmt->execute([$progress,$progress>=100?'concluida':($progress>0?'em_andamento':'a_fazer'),$id,$user['setor']]);$stmt=$pdo->prepare('INSERT INTO meta_atualizacoes(meta_id,usuario_id,progresso_percentual,comentario) VALUES(?,?,?,?)');$stmt->execute([$id,$user['id'],$progress,trim($_POST['comentario']??'')?:null]);header('Location: '.app_path('calendario.html?salvo=atualizacao'));exit;}}}
   else{$title=trim($_POST['titulo_evento']??'');$sector=$user['setor'];$start=str_replace('T',' ',$_POST['inicio']??'');if(strlen($start)===16)$start.=':00';if($title===''||!in_array($sector,$sectors,true)||!DateTime::createFromFormat('Y-m-d H:i:s',$start))$error='Preencha título e data/hora válida.';else{$stmt=$pdo->prepare('INSERT INTO eventos(titulo,descricao,setor,inicio,categoria,criado_por) VALUES(?,?,?,?,?,?)');$stmt->execute([$title,trim($_POST['descricao_evento']??'')?:null,$sector,$start,$_POST['categoria']??'outros',$user['id']]);header('Location: '.app_path('calendario.html?salvo=evento'));exit;}}
  }elseif($action==='checklist') {if($admin){http_response_code(403);exit('O checklist individual é para usuárias comuns.');}$id=(int)($_POST['meta_id']??0);$done=isset($_POST['concluida'])?1:0;$stmt=$pdo->prepare('SELECT id FROM metas WHERE id=? AND setor=?');$stmt->execute([$id,$user['setor']]);if(!$stmt->fetch())$error='Meta não encontrada no seu setor.';else{$stmt=$pdo->prepare('INSERT INTO meta_checklist(meta_id,usuario_id,concluida) VALUES(?,?,?) ON CONFLICT (meta_id,usuario_id) DO UPDATE SET concluida=EXCLUDED.concluida,atualizado_em=now()');$stmt->execute([$id,$user['id'],$done]);header('Location: '.app_path('calendario.html?salvo=checklist'));exit;}}
 }
}
$goalSql=$admin?'SELECT m.*,0 AS checklist_concluida FROM metas m WHERE m.setor=? ORDER BY m.semana_inicio,m.id':'SELECT m.*,COALESCE(c.concluida,0) AS checklist_concluida FROM metas m LEFT JOIN meta_checklist c ON c.meta_id=m.id AND c.usuario_id=? WHERE m.setor=? ORDER BY m.semana_inicio,m.id';$stmt=$pdo->prepare($goalSql);$admin?$stmt->execute([$user['setor']]):$stmt->execute([$user['id'],$user['setor']]);$metas=$stmt->fetchAll();
$eventSql='SELECT * FROM eventos WHERE setor=? ORDER BY inicio';$stmt=$pdo->prepare($eventSql);$stmt->execute([$user['setor']]);$events=$stmt->fetchAll();
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function dbr(string $v):string{return date('d/m/Y',strtotime($v));}
$html=file_get_contents(__DIR__.'/../calendario.html');if(!$admin)$html=preg_replace('~<button[^>]*>\s*\+ Novo evento\s*</button>~si','',$html);else $html=preg_replace('~<button([^>]*)>\s*\+ Novo evento\s*</button>~si','<a href="#acoes-calendario" class="bg-blue-950 hover:bg-blue-900 text-white rounded-lg px-4 py-2 text-sm font-semibold whitespace-nowrap">+ Novo evento / meta</a>',$html,1);
$success=['meta'=>'Meta adicionada.','atualizacao'=>'Atualização salva.','evento'=>'Evento adicionado.','checklist'=>'Checklist atualizado.'][$_GET['salvo']??'']??'';
$goalCards='';foreach($metas as $m){$goalCards.='<article class="border rounded-lg p-4"><div class="flex justify-between"><div><b>'.h($m['titulo']).'</b><p class="text-xs text-gray-500">'.h(sector_label($m['setor'])).' · '.dbr($m['semana_inicio']).'–'.dbr($m['semana_fim']).'</p></div><b>'.number_format((float)$m['progresso_percentual'],0).'%</b></div>'.($m['descricao']?'<p class="text-sm mt-2">'.h($m['descricao']).'</p>':'');if($admin)$goalCards.='<form method="post" class="grid sm:grid-cols-[100px_1fr_auto] gap-2 mt-3"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="update_meta"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><input aria-label="Progresso" type="number" min="0" max="100" name="progresso" value="'.(float)$m['progresso_percentual'].'" class="border rounded p-2"><input aria-label="Atualização" name="comentario" placeholder="Atualização" class="border rounded p-2"><button class="bg-blue-900 text-white rounded px-3">Atualizar</button></form>';else $goalCards.='<form method="post" class="mt-3"><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="checklist"><input type="hidden" name="meta_id" value="'.(int)$m['id'].'"><label><input type="checkbox" name="concluida" value="1" '.($m['checklist_concluida']?'checked':'').' onchange="this.form.submit()"> Minha meta concluída</label></form>';$goalCards.='</article>';}
$eventCards='';foreach($events as $e)$eventCards.='<article class="border rounded-lg p-3"><b>'.h($e['titulo']).'</b><p class="text-xs text-gray-500">'.h(sector_label($e['setor'])).' · '.date('d/m/Y H:i',strtotime($e['inicio'])).'</p>'.($e['descricao']?'<p class="text-sm">'.h($e['descricao']).'</p>':'').'</article>';
$adminForms=$admin?'<div id="acoes-calendario" class="grid lg:grid-cols-2 gap-4"><form method="post" class="bg-gray-50 border rounded-xl p-4 space-y-3"><h3 class="font-bold">Adicionar meta</h3><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="create_meta"><input required name="titulo" maxlength="200" placeholder="Título da meta" class="w-full border rounded p-2"><select required name="setor" class="w-full border rounded p-2"><option value="">Setor</option><option value="engenharia">Engenharia</option><option value="administrativo">Administrativo</option><option value="obras">Obras</option></select><textarea name="descricao" placeholder="Descrição" class="w-full border rounded p-2"></textarea><div class="grid grid-cols-2 gap-2"><input type="date" name="semana_inicio" required class="border rounded p-2"><input type="date" name="semana_fim" required class="border rounded p-2"></div><button class="bg-blue-950 text-white rounded px-4 py-2">Salvar meta</button></form><form method="post" class="bg-gray-50 border rounded-xl p-4 space-y-3"><h3 class="font-bold">Adicionar evento</h3><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="create_event"><input required name="titulo_evento" maxlength="200" placeholder="Título do evento" class="w-full border rounded p-2"><select required name="setor_evento" class="w-full border rounded p-2"><option value="">Setor</option><option value="engenharia">Engenharia</option><option value="administrativo">Administrativo</option><option value="obras">Obras</option></select><input type="datetime-local" name="inicio" required class="w-full border rounded p-2"><select name="categoria" class="w-full border rounded p-2"><option value="outros">Outros</option><option value="eventos">Eventos</option><option value="reuniao">Reunião</option><option value="fiscalizacao">Fiscalização</option><option value="manutencao">Manutenção</option></select><textarea name="descricao_evento" placeholder="Descrição" class="w-full border rounded p-2"></textarea><button class="bg-blue-950 text-white rounded px-4 py-2">Salvar evento</button></form></div>':'';
$section='<section class="px-4 md:px-6 pb-8 space-y-5">'.($error?'<p class="bg-red-50 text-red-700 p-3 rounded">'.h($error).'</p>':'').($success?'<p class="bg-green-50 text-green-700 p-3 rounded">'.h($success).'</p>':'').$adminForms.'<div class="grid lg:grid-cols-2 gap-5"><div class="bg-white border rounded-xl p-5"><h2 class="font-bold text-lg mb-3">Metas</h2><div class="space-y-3">'.($goalCards?:'<p class="text-sm text-gray-500">Não há metas para exibir.</p>').'</div></div><div class="bg-white border rounded-xl p-5"><h2 class="font-bold text-lg mb-3">Eventos</h2><div class="space-y-3">'.($eventCards?:'<p class="text-sm text-gray-500">Não há eventos cadastrados.</p>').'</div></div></div></section>';
$calendarEventForm=$admin?'<div id="acoes-calendario" class="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm"><form method="post" class="space-y-3"><h3 class="font-bold text-lg">Adicionar evento</h3><input type="hidden" name="csrf_token" value="'.h(csrf_token()).'"><input type="hidden" name="action" value="create_event"><input required name="titulo_evento" maxlength="200" placeholder="Título do evento" class="w-full rounded-xl border border-gray-200 p-3"><select required name="setor_evento" class="w-full rounded-xl border border-gray-200 bg-white p-3"><option value="">Setor</option><option value="engenharia">Engenharia</option><option value="administrativo">Administrativo</option><option value="obras">Obras</option></select><input type="datetime-local" name="inicio" required class="w-full rounded-xl border border-gray-200 p-3"><select name="categoria" class="w-full rounded-xl border border-gray-200 bg-white p-3"><option value="outros">Outros</option><option value="eventos">Eventos</option><option value="reuniao">Reunião</option><option value="fiscalizacao">Fiscalização</option><option value="manutencao">Manutenção</option></select><textarea name="descricao_evento" placeholder="Descrição" class="w-full rounded-xl border border-gray-200 p-3"></textarea><button class="rounded-xl bg-blue-950 px-4 py-2 font-semibold text-white">Salvar evento</button></form></div>':'';
if($admin)$calendarEventForm=preg_replace('~<select required name="setor_evento".*?</select>~s','<input type="hidden" name="setor_evento" value="'.h($user['setor']).'"><div class="rounded-xl border border-gray-200 bg-gray-50 p-3 text-sm text-slate-700">Setor da equipe: <strong>'.h(sector_label($user['setor'])).'</strong></div>',$calendarEventForm);
$section='<section class="px-4 md:px-6 pb-8 space-y-5">'.($error?'<p class="bg-red-50 text-red-700 p-3 rounded">'.h($error).'</p>':'').($success?'<p class="bg-green-50 text-green-700 p-3 rounded">'.h($success).'</p>':'').$calendarEventForm.'</section>';
$position=strrpos($html,'</main>');if($position!==false)$html=substr_replace($html,$section,$position,0);
$calendarItems=[];
foreach($metas as $meta)$calendarItems[]=['type'=>'meta','title'=>$meta['titulo'],'description'=>$meta['descricao'],'sector'=>$meta['setor'],'start_date'=>$meta['semana_inicio'],'end_date'=>$meta['semana_fim'],'status'=>$meta['status'],'progress'=>(float)$meta['progresso_percentual']];
foreach($events as $event)$calendarItems[]=['type'=>'event','title'=>$event['titulo'],'description'=>$event['descricao'],'sector'=>$event['setor'],'date'=>substr($event['inicio'],0,10),'time'=>substr($event['inicio'],11,5),'category'=>$event['categoria']];
$calendarItemsJson=json_encode($calendarItems,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
$html=str_replace('<script id="calendar-meta-data" type="application/json">[]</script>','<script id="calendar-meta-data" type="application/json">'.($calendarItemsJson?:'[]').'</script>',$html);
$html=str_replace('+ Novo evento / meta','+ Novo evento',$html);
echo $html;
